-- 8. RÉACTIVER CONTRAINTES
-- chk_date_obtention non réactivée : 279 certifications "Obtenue" de l'export Salesforce
-- n'ont pas de date_obtention renseignée (champ historiquement non systématique).
ALTER TABLE certifications ADD CONSTRAINT chk_date_prev CHECK (statut != 'Planifiée' OR date_previsionnelle IS NOT NULL);
ALTER TABLE consultants ADD CONSTRAINT consultants_manager_id_fkey FOREIGN KEY (manager_id) REFERENCES consultants(id) ON DELETE SET NULL;
ALTER TABLE vouchers ADD CONSTRAINT vouchers_certification_id_fkey FOREIGN KEY (certification_id) REFERENCES certifications(id) ON DELETE SET NULL;
ALTER TABLE certifications ADD CONSTRAINT fk_certif_voucher FOREIGN KEY (voucher_id) REFERENCES vouchers(id) ON DELETE SET NULL;

